      });

      // Check events file
      const sessionsDir = path.join(tempDir, 'sessions');
      const sessions = await fs.readdir(sessionsDir).catch(() => []);

      if (sessions.length > 0) {
        const eventsPath = path.join(sessionsDir, sessions[0], 'events.jsonl');
